#### Task Overview
**Task ID:** T-008  
**Title:** On-device NLP pipeline scaffold  
**Owner Lane:** services_utilities  

I'm tasked with building the on-device Natural Language Processing (NLP) pipeline, which will include transcription and tagging. The goal is to ensure that the transcript text never leaves the local process and that the pipeline runs fully on-device.

#### Steps
1. **Create TranscriptionCoordinator**: This class will handle the transcription of audio entries.
2. **Implement AutoTagger**: This class will suggest tags based on the transcribed text.
3. **Integrate with RecordingController**: Ensure the transcription starts when recording is finalized and tagging happens after transcription.
4. **Handle Transcription Status Updates**: Update the `Entry` model with transcription status.

#### Implementation

**1. Create TranscriptionCoordinator**
```swift
import Foundation
import Speech

final class TranscriptionCoordinator {
    private let audioFileURL: URL
    private var recognitionTask: SFSpeechRecognitionTask?

    init(audioFileURL: URL) {
        self.audioFileURL = audioFileURL
    }

    func transcribe(entryID: UUID, onCompletion: @escaping (TranscriptionStatus) -> Void) {
        guard let recognizer = SFSpeechRecognizer() else {
            onCompletion(.unavailable)
            return
        }

        if !recognizer.isAvailable {
            onCompletion(.unavailable)
            return
        }

        let request = SFSpeechURLRecognitionRequest(url: audioFileURL)
        request.shouldReportPartialResults = true

        recognitionTask = recognizer.recognitionTask(with: request) { result, error in
            guard let result = result else {
                if let error = error as? NSError, error.domain == kCLErrorDomain && error.code == CLError.Code.locationUnknown.rawValue {
                    onCompletion(.error)
                } else {
                    onCompletion(.unavailable)
                }
                self.recognitionTask = nil
                return
            }

            let transcription = result.bestTranscription.formattedString
            print("Transcription: \(transcription)")

            if result.isFinal {
                // Update the Entry with the transcript text and status
                Task {
                    let context = ModelContainerFactory.make(cloudKitEnabled: false)
                    if let entry = await context.query(for: Entry.self, where: \Entry.id == entryID).first {
                        entry.cachedTranscriptText = transcription
                        entry.transcriptionStatus = .ready

                        do {
                            try await context.save()
                        } catch {
                            print("Error saving transcription to database: \(error)")
                            onCompletion(.error)
                        }
                    }
                }

                onCompletion(.ready)
                self.recognitionTask = nil
            }
        }
    }

    func stopTranscription() {
        recognitionTask?.cancel()
        recognitionTask = nil
    }
}
```

